// Законы: решения, которые не заканчиваются газетой на следующее утро. Принятый закон ложится
// в «Свод законов» и действует каждый ход, пока его не отменят: двигает опоры власти и отношение
// групп, открывает новые дела. К концу партии по своду видно, каким президентом вы были.
//
// Слоты в текстах — как в карточках дел: {fac:блок}, {fig:блок}, {capital}, {country}.
// Законопроект вносит группа bloc: если её в стране нет, закон в этой партии не предлагают.
import type { CardCondition, CardChoice } from "./events.ts";
import type { ActionTag, Bloc, ResourceDelta, ResourceKey } from "../game/types.ts";

export interface LawDef {
  id: string;
  title: string;                 // официальное название: «Об иностранных агентах»
  short: string;                 // что меняет, одной строкой — для свода
  bloc: Bloc;                    // кто вносит законопроект
  allies: Bloc[];                // кто ещё за закон, кроме авторов
  foes: Bloc[];                  // кто против: реакции и отношения следуют сути закона, а не общим тегам
  countries?: string[];
  conflicts?: string[];          // взаимоисключающие законы: при одном другой не вносят
  tags: ActionTag[];             // провести закон
  veto: ActionTag[];             // отклонить
  costs?: Partial<Record<ResourceKey, string>>; // цена проведения именно этого закона
  vetoCosts?: Partial<Record<ResourceKey, string>>;
  perTurn: ResourceDelta;        // каждый ход, пока закон действует
  drift?: Partial<Record<Bloc, number>>; // отношение групп блока, каждый ход
  pitch: string;                 // как законопроект ложится на стол
  passed: string; failed: string; vetoed: string; // сцены газеты
  head: { passed: string; failed: string; vetoed: string };
  followUp: { title: string; source: string; description: string; when?: CardCondition; choices: CardChoice[] };
}

